import{d as g,C as n,o as d,c as h,E as i,a3 as a}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"未济卦","description":"第六十四卦·火水未济——火在水上，各奔东西；未完成才是常态，行进中本身就是亨通。","frontmatter":{"title":"未济卦","description":"第六十四卦·火水未济——火在水上，各奔东西；未完成才是常态，行进中本身就是亨通。","category":"hexagram","aliases":["未济","火水未济"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-64.md","filePath":"yijing/hexagrams/hexagram-64.md","lastUpdated":1787800334000}'),p={name:"yijing/hexagrams/hexagram-64.md"},q=g({...p,setup(u){const o=[{id:"weiji",term:"未济",pinyin:"wèi jì",meaning:"渡河尚未完成。济为渡，未为尚未。",context:"六十四卦最后一卦，以未完成压轴收尾。"},{id:"qi",term:"汔",pinyin:"qì",meaning:"几乎、接近。「汔济」即几乎渡到对岸。",context:"最后一步最危险。"},{id:"ruqiwei",term:"濡其尾",pinyin:"rú qí wěi",meaning:"打湿尾巴——小狐渡河时入水过深，力不从心。",context:"轻率湿尾，开始就要慎重。"},{id:"lin",term:"吝"},{id:"yeqilun",term:"曳其轮",pinyin:"yè qí lún",meaning:"拖住车轮、主动刹车放慢。",context:"险中要的是稳，不是快。"},{id:"zhen",term:"贞",sense:1},{id:"zhengxiong",term:"征凶",pinyin:"zhēng xiōng",meaning:"强行出征有凶险。",context:"位不当，硬冲必凶。"},{id:"lishedachuan",term:"利涉大川",pinyin:"lì shè dà chuān",meaning:"利于涉越大河——以涉代征。",context:"放下征服欲，探索代替征服，在险中看见光。"},{id:"zhenyong",term:"震用",pinyin:"zhèn yòng",meaning:"以震动之势持续用力。",context:"不是强攻，是久久为功。"},{id:"faguifang",term:"伐鬼方",pinyin:"fá guǐ fāng",meaning:"征伐西北强族鬼方。",context:"苦战三年，久久为功，赏自然来。"},{id:"huiwang",term:"悔亡"},{id:"junzizhiguang",term:"君子之光",pinyin:"jūn zǐ zhī guāng",meaning:"君子的光辉——从内心发出的光。",context:"光从内心来，有孚自然发。"},{id:"youfu",term:"有孚"},{id:"rushou",term:"濡其首",pinyin:"rú qí shǒu",meaning:"水淹到头、打湿头。",context:"亦不知节——分寸即孚。"},{id:"shishi",term:"失是",pinyin:"shī shì",meaning:"失去正理、失去时机。",context:"有孚失是，即失去证明孚的机会。"},{id:"shenbianwujufang",term:"慎辨物居方",pinyin:"shèn biàn wù jū fāng",meaning:"谨慎分辨物类、使万物各得其所。",context:"未成之时，先辨清万物该放哪里。"},{id:"hui",term:"晖",pinyin:"huī",meaning:"光辉。「其晖吉也」——光芒所及皆吉。"}],e=[{position:"初六",type:"yin",text:"濡其尾，吝。",xiang:"濡其尾，亦不知极也。",textModern:"小狐渡河沾湿了尾巴，憾惜——一开始就轻率冒进，湿了尾。",xiangModern:"沾湿尾巴，是因为不知道河有多宽、自己的能力边界在哪。"},{position:"九二",type:"yang",text:"曳其轮，贞吉。",xiang:"九二贞吉，中以行正也。",textModern:"拖住车轮、主动放慢，守正吉祥。",xiangModern:"九二守正吉祥，是因为居中而行正——险中要的是稳，不是快。"},{position:"六三",type:"yin",text:"未济，征凶，利涉大川。",xiang:"未济征凶，位不当也。",textModern:"尚未渡过，贸然出征有凶险；但利于涉越大河——以涉代征。",xiangModern:"未完成就硬冲有凶，因为位置不当——放下征服欲，用探索代替征服。"},{position:"九四",type:"yang",text:"贞吉悔亡，震用伐鬼方，三年有赏于大国。",xiang:"贞吉悔亡，志行也。",textModern:"守正吉祥、悔恨消亡；以震动之势持久用力，讨伐鬼方，苦战三年后得到大国的封赏。",xiangModern:"守正而悔亡，是因为志向得以实行——久久为功，赏自然来。"},{position:"六五",type:"yin",text:"贞吉无悔，君子之光，有孚，吉。",xiang:"君子之光，其晖吉也。",textModern:"守正吉祥、无所悔恨；君子的光辉源于诚信，吉祥。",xiangModern:"君子的光辉，其光芒所及皆吉——光从内心来，有孚自然发。"},{position:"上九",type:"yang",text:"有孚于饮酒，无咎。濡其首，有孚失是。",xiang:"饮酒濡首，亦不知节也。",textModern:"心怀诚信地饮酒，没有灾咎；但喝到水淹了头，再诚信也失去正理。",xiangModern:"饮酒喝到湿了头，是不知节制——孚需要时机与分寸。"}];return(m,t)=>{const r=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),s=n("DaoKeywordCards");return d(),h("div",null,[i(r,{name:"未济",fullName:"火水未济",upper:"☲",lower:"☵",guaCi:"未济，亨。小狐汔济，濡其尾，无攸利。",pinyin:["wèi","jì"],element:"火",direction:"南",insight:"火在水上，各奔东西；六爻皆不当位，却刚柔相应——未完成才是常态，行进中本身就是亨通。",guaSlug:"64huoshuoweiji",lines:e}),t[0]||(t[0]=a('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>火在水上，未济。君子以慎辨物居方。</p><p>火在水上——火往上烧、水往下流，各奔东西、暂不相交，是渡河未成之象；君子由此领悟，要谨慎地分辨物类，让万物各得其所。</p><p>「慎辨物居方」——<strong>慎</strong>是谨慎；<strong>辨物</strong>是分辨事物的类与质；<strong>居方</strong>是让它们各安其位。未济之时，事未成、物未定，最该做的不是急着济，而是先辨清每一样东西该放在哪里。</p><p>分形结构：</p><ul><li>辨物（分辨）→ 微观：分清自己手里的牌，哪些能打、哪些要等</li><li>居方（定位）→ 宏观：让资源各就其位，为将来的渡河留出通道</li></ul><p>火水各奔，不是没有济的可能，是时机未到。慎辨物居方，就是先把各奔的东西摆对位置——位置对了，水火终会相交；位置乱了，永远擦肩而过。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>未济亨，柔得中也。小狐汔济，未出中也。濡其尾，无攸利，不续终也。虽不当位，刚柔应也。</p><p>逐句释义：</p><ul><li><strong>未济亨，柔得中也</strong> —— 未济之所以亨通，在于六五柔爻居中得位。越是未完成，越要柔——不是硬冲，是柔而得中。</li><li><strong>小狐汔济，未出中也</strong> —— 小狐几乎渡到对岸，却还没走出中间那一段。最后一步最危险：济了一半、最接近成功的时候，最容易失足。</li><li><strong>濡其尾，无攸利，不续终也</strong> —— 尾巴被打湿、无所利，是因为没能把最后一段接续到底。功亏一篑，不是败在开头，是败在不能续终。</li><li><strong>虽不当位，刚柔应也</strong> —— 六爻虽皆不当位，但刚柔相应：初六应九四、九二应六五、六三应上九。不完美，却处处有回应。</li></ul><blockquote><p><strong>未济哲学</strong>：既济是六十四卦中唯一六爻皆正的卦——可《周易》偏偏以六爻皆不当位的未济收尾。正不是等来的，是不完美中一点点应出来的。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',13)),i(l,{element:"火",guaSlug:"64huoshuoweiji",glossary:o,items:e}),t[1]||(t[1]=a('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初六-·-濡其尾-吝" tabindex="-1">初六 · 濡其尾，吝 <a class="header-anchor" href="#初六-·-濡其尾-吝" aria-label="Permalink to &quot;初六 · 濡其尾，吝&quot;">​</a></h3><ul><li><strong>濡</strong> → 打湿</li><li><strong>尾</strong> → 小狐渡河，尾巴是入水最深的部位</li><li><strong>吝</strong> → 憾惜、艰难</li></ul><p>初六阴居坎体之始，是渡河的第一步，也是小狐之尾。轻率下水、入水过深，尾巴先湿——「亦不知极也」：不知道河的边界，也不知道自己能力的极限。开始就要慎重：第一脚踩深了，后面每一步都带着湿尾。</p><blockquote><p>核心洞见：最后一步最危险，但第一步的轻率，就已经埋下湿尾。开始就要慎重。</p></blockquote><h3 id="九二-·-曳其轮-贞吉" tabindex="-1">九二 · 曳其轮，贞吉 <a class="header-anchor" href="#九二-·-曳其轮-贞吉" aria-label="Permalink to &quot;九二 · 曳其轮，贞吉&quot;">​</a></h3><ul><li><strong>曳</strong> → 拖、拉</li><li><strong>其轮</strong> → 车轮</li><li><strong>贞吉</strong> → 守正吉祥</li></ul><p>九二阳爻居中得正，本是有能力快的一爻——但爻辞让它曳其轮：主动拖住车轮、放慢。象曰「中以行正」：居中而行正，险中要的是稳，不是快。未济的河道上，最会渡河的人不是划得最快的人，是知道什么时候该拖住轮子的人。</p><blockquote><p>核心洞见：主动放慢守正。险中要的是稳，不是快。</p></blockquote><h3 id="六三-·-未济-征凶-利涉大川" tabindex="-1">六三 · 未济，征凶，利涉大川 <a class="header-anchor" href="#六三-·-未济-征凶-利涉大川" aria-label="Permalink to &quot;六三 · 未济，征凶，利涉大川&quot;">​</a></h3><ul><li><strong>未济</strong> → 尚未渡过</li><li><strong>征凶</strong> → 强行出征，凶险</li><li><strong>利涉大川</strong> → 利于涉越大河</li></ul><p>六三阴爻居刚位、位不当，正是「征凶」的位置。但紧跟着是「利涉大川」——这是未济卦最关键的一句：<strong>以涉代征</strong>。征是征服，涉是探索；放下征服欲，用探索代替征服，就能在险中看见光。位不当不是不能动，是不能用硬冲的方式动。</p><blockquote><p>核心洞见：以涉代征——放下征服欲，探索代替征服，在险中看见光。</p></blockquote><h3 id="九四-·-贞吉悔亡-震用伐鬼方-三年有赏于大国" tabindex="-1">九四 · 贞吉悔亡，震用伐鬼方，三年有赏于大国 <a class="header-anchor" href="#九四-·-贞吉悔亡-震用伐鬼方-三年有赏于大国" aria-label="Permalink to &quot;九四 · 贞吉悔亡，震用伐鬼方，三年有赏于大国&quot;">​</a></h3><ul><li><strong>震用</strong> → 以震动之势持续用力</li><li><strong>伐鬼方</strong> → 征伐强族鬼方</li><li><strong>三年有赏于大国</strong> → 苦战三年，得到大国的封赏</li></ul><p>九四阳爻，与初六相应，是未济里最能成事的一爻。爻辞给的不是强攻，是「震用」——不是硬碰硬地攻，是持续地震动、久久为功。三年，不是三年都打不下来，是三年都在正确地用力。久久为功，赏自然来。</p><blockquote><p>核心洞见：不是强攻是震动——久久为功，赏自然来。</p></blockquote><h3 id="六五-·-贞吉无悔-君子之光-有孚-吉" tabindex="-1">六五 · 贞吉无悔，君子之光，有孚，吉 <a class="header-anchor" href="#六五-·-贞吉无悔-君子之光-有孚-吉" aria-label="Permalink to &quot;六五 · 贞吉无悔，君子之光，有孚，吉&quot;">​</a></h3><ul><li><strong>贞吉无悔</strong> → 守正吉祥、无所悔恨</li><li><strong>君子之光</strong> → 君子的光辉</li><li><strong>有孚</strong> → 有诚信</li></ul><p>六五阴爻居君位、柔而得中，正是彖传「柔得中」的落点。君子之光——光不是照出来的，是从内心发出来的；有孚，才有光。柔而得中是生命力：不靠权力压人，靠信实感人。未完成的黑夜里，君子之光依然在发出。</p><blockquote><p>核心洞见：光从内心来，有孚自然发。柔而得中，就是未济的生命力。</p></blockquote><h3 id="上九-·-有孚于饮酒-无咎。濡其首-有孚失是" tabindex="-1">上九 · 有孚于饮酒，无咎。濡其首，有孚失是 <a class="header-anchor" href="#上九-·-有孚于饮酒-无咎。濡其首-有孚失是" aria-label="Permalink to &quot;上九 · 有孚于饮酒，无咎。濡其首，有孚失是&quot;">​</a></h3><ul><li><strong>有孚于饮酒</strong> → 心怀诚信地饮酒</li><li><strong>无咎</strong> → 没有灾咎</li><li><strong>濡其首</strong> → 喝到水淹了头</li><li><strong>有孚失是</strong> → 再诚信，也失去了正理、失去了证明孚的机会</li></ul><p>未济走到上九，将济未济、大局将定——此时可以有孚于饮酒：心怀诚信、从容放松，无咎。但「濡其首，有孚失是」——喝到水淹了头，就失去了把握分寸的时机。孚需要时机：该静的时候静，该饮的时候饮；分寸一失，孚也失去证明自己的机会。</p><blockquote><p>核心洞见：孚需时机。有孚饮酒无咎，濡其首则失去证明孚的机会。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',26)),i(s,{title:"字词释义",items:[{term:"未济",pinyin:["wèi","jì"],meaning:"渡河尚未完成。济为渡，未为尚未。六十四卦最后一卦，以未完成压轴收尾。"},{term:"汔济",pinyin:["qì","jì"],meaning:"几乎渡到对岸。「小狐汔济」——差一步就成功，恰恰最危险。"},{term:"濡其尾",pinyin:["rú","qí","wěi"],meaning:"打湿尾巴——小狐渡河入水过深、力不从心。尾湿是轻率的代价。"},{term:"曳其轮",pinyin:["yè","qí","lún"],meaning:"拖住车轮、主动刹车放慢。险中要的是稳，不是快。"},{term:"征凶",pinyin:["zhēng","xiōng"],meaning:"强行出征有凶险。位不当，硬冲必凶。"},{term:"利涉大川",pinyin:["lì","shè","dà","chuān"],meaning:"利于涉越大河——以涉代征，放下征服欲，用探索代替征服。"},{term:"震用",pinyin:["zhèn","yòng"],meaning:"以震动之势持续用力。不是强攻，是久久为功。"},{term:"伐鬼方",pinyin:["fá","guǐ","fāng"],meaning:"征伐西北强族鬼方。苦战三年，久久为功，赏自然来。"},{term:"君子之光",pinyin:["jūn","zǐ","zhī","guāng"],meaning:"君子的光辉——从内心发出的光，有孚自然发。"},{term:"有孚"},{term:"濡其首",pinyin:["rú","qí","shǒu"],meaning:"水淹到头、打湿头。亦不知节——分寸即孚。"},{term:"失是",pinyin:["shī","shì"],meaning:"失去正理、失去时机。「有孚失是」——失去证明孚的机会。"},{term:"慎辨物居方",pinyin:["shèn","biàn","wù","jū","fāng"],meaning:"谨慎分辨物类、使万物各得其所。未成之时，先辨清万物该放哪里。"},{term:"不续终",pinyin:["bù","xù","zhōng"],meaning:"不能接续到底。功亏一篑，不是败在开头，是败在不能续终。"}]}),t[2]||(t[2]=a('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>未济讲的是<strong>渡河尚未完成的持续状态</strong>。上离（火）在下坎（水）上——火往上烧、水往下流，水火相背、暂不相交；六爻全部不当位，却刚柔相应。这是六十四卦的压轴：易经不是以「完成」收尾，是以「未完成」收尾。</p><p>卦辞「未济，亨」——未完成，反而亨通。小狐汔济，濡其尾：几乎到岸，却湿了尾。最后一步最危险，也最需要慎。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>未济是易经的最后一卦，也是整个宇宙观的落点：<strong>没有终点，只有下一个开始</strong>。既济是完成，未济是继续；完成是暂时的，未完成才是常态。未济的亨通，在于「柔得中」——不硬冲、不焦躁，在不确定里保持柔韧。</p><p>易经三义在这里收束：<strong>变易</strong>（万物皆变，所以永无终点）、<strong>不易</strong>（变的规律不变，所以「未济亨」可信）、<strong>简易</strong>（大道至简，所以柔得中就够了）。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>开始就要慎重——第一脚踩深了，后面每一步都带着湿尾</li><li>险中求稳——主动放慢（曳其轮），守正</li><li>以涉代征——放下征服欲，用探索代替征服</li><li>久久为功——不是强攻是震动，三年有赏</li><li>光从内心来——有孚自然发，柔而得中</li><li>孚需时机——该饮时饮，分寸一失，孚也失去机会</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>未济卦的完整地图：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>功课</th><th>关键词</th></tr></thead><tbody><tr><td>卦辞</td><td>未济亨，小狐汔济濡其尾</td><td>未完成才是常态，最后一步最危险</td><td>未完成即亨通</td></tr><tr><td>初六</td><td>濡其尾，吝</td><td>开始就要慎重，轻率湿尾</td><td>不知极</td></tr><tr><td>九二</td><td>曳其轮，贞吉</td><td>主动放慢守正</td><td>险中求稳</td></tr><tr><td>六三</td><td>未济征凶，利涉大川</td><td>以涉代征，探索代替征服</td><td>在险中看见光</td></tr><tr><td>九四</td><td>震用伐鬼方，三年有赏于大国</td><td>久久为功，不是强攻是震动</td><td>久久为功</td></tr><tr><td>六五</td><td>贞吉无悔，君子之光，有孚吉</td><td>光从内心来，有孚自然发</td><td>柔而得中</td></tr><tr><td>上九</td><td>有孚于饮酒无咎，濡其首有孚失是</td><td>孚需时机，分寸即孚</td><td>孚需时机</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>未完成才是常态</strong>——天地之间没有真正的终点</li><li><strong>柔而得中是生命力</strong>——不硬冲，在不确定里保持柔韧</li><li><strong>以涉代征</strong>——放下征服欲，探索代替征服，在险中看见光</li><li><strong>久久为功</strong>——不是强攻是震动，三年有赏</li><li><strong>君子之光在未完成里发出</strong>——光从内心来，有孚自然发</li><li><strong>孚需时机</strong>——分寸一失，孚也失去证明自己的机会</li><li><strong>易经三义</strong>——变易、不易、简易，未济是三义的收束</li><li><strong>慎辨物居方</strong>——未成之时，先辨清万物该放哪里</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>未济对应我此刻的状态——几个领域都「未济」，而这正是常态：</p><ul><li><strong>羽毛球 → 九二曳其轮</strong>：主动放慢守正，险中要的是稳，不是快</li><li><strong>易经研习 → 六三利涉大川</strong>：以涉代征，用探索代替征服</li><li><strong>全栈转型 → 九四震用伐鬼方</strong>：久久为功，三年有赏</li><li><strong>日常 → 六五君子之光</strong>：有孚自然发，光从内心来</li></ul><p>产品构思 <strong>《dao-mirror》</strong>——省己之镜：既济之患在感知消失，未济之机在时时自省。既济教「思患豫防」，未济教「慎辨物居方」——每天照镜子，看看自己把什么辨清了、把什么放对了地方。</p><p>未济不是等失败，是把「未完成」当作常态来活：行进中本身就是亨通，君子之光，正要在未完成的黑夜里发出。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：既济（第六十三卦）、离（第三十卦）、坎（第二十九卦）</li><li>既济与未济的合观：六十四卦以既济（完成）居六十三，却以未济（未完成）压轴收尾——没有终点，只有下一个开始。渡完这条河，前面就是下一条河：既济是未济的开始，未济也是下一个既济。</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',21))])}}});export{x as __pageData,q as default};
